package com.rims;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String sku; @Column(nullable=false) String name; String category; BigDecimal price; String description; int quantity; int minStock; public Product(){} public Product(String s,String n,String c,double p,int q,int m,String d){sku=s;name=n;category=c;price=BigDecimal.valueOf(p);quantity=q;minStock=m;description=d;} public Long getId(){return id;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public int getMinStock(){return minStock;} public void setMinStock(int v){minStock=v;} }
@Entity class Supplier { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String name; String contact; String email; String phone; public Supplier(){} public Supplier(String n,String c,String e,String p){name=n;contact=c;email=e;phone=p;} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getContact(){return contact;} public void setContact(String v){contact=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} }
@Entity class StockTransaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long productId; String productName; String type; int quantity; LocalDateTime transactionDate; public StockTransaction(){} public StockTransaction(Long p,String n,String t,int q){productId=p;productName=n;type=t;quantity=q;transactionDate=LocalDateTime.now();} public Long getId(){return id;} public Long getProductId(){return productId;} public String getProductName(){return productName;} public String getType(){return type;} public int getQuantity(){return quantity;} public LocalDateTime getTransactionDate(){return transactionDate;} }
